#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

using ll = long long;
const ll MOD = 1000000007LL;

ll modPow(ll a, ll b) {
    ll result = 1;
    a %= MOD;
    while (b > 0) {
        if (b & 1) result = result * a % MOD;
        a = a * a % MOD;
        b >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, K;
    ll m;
    cin >> n >> m >> K;

    if (n <= 0 || K < 0) {
        cout << (n == 0 && K == 0 ? 1 : 0) << '\n';
        return 0;
    }

    int limit = min(n, K);
    vector<ll> combination(limit + 1, 0);
    combination[0] = 1;

    for (int i = 1; i <= n; ++i) {
        for (int j = min(i, limit); j >= 1; --j) {
            combination[j] += combination[j - 1];
            if (combination[j] >= MOD) combination[j] -= MOD;
        }
    }

    ll quotient = m / n;
    int remainder = static_cast<int>(m % n);

    vector<ll> coefficient1(limit + 1);
    vector<ll> coefficient2(limit + 1);
    for (int k = 0; k <= limit; ++k) {
        coefficient1[k] = modPow(combination[k], quotient);
        coefficient2[k] = modPow(combination[k], quotient + 1);
    }

    vector<ll> dp(K + 1, 0), next(K + 1, 0);
    dp[0] = 1;

    for (int i = 0; i < n; ++i) {
        fill(next.begin(), next.end(), 0);
        const vector<ll>& coefficient =
            (i < remainder ? coefficient2 : coefficient1);

        for (int j = 0; j <= K; ++j) {
            if (dp[j] == 0) continue;
            int maxK = min(limit, K - j);
            for (int k = 0; k <= maxK; ++k) {
                next[j + k] =
                    (next[j + k] + dp[j] * coefficient[k]) % MOD;
            }
        }
        dp.swap(next);
    }

    cout << dp[K] << '\n';
    return 0;
}

